                .user(owner)
                .stripePaymentMethodId(token)
                .brand("visa")
                .last4("4242")
                .expMonth(expMonth)
                .expYear(expYear)
                .deleted(deleted)
                .build());
    }

    private UserPaymentMethod validCard(User owner, String token) {
        return saveCard(owner, token, 12, YearMonth.now().getYear() + 3, false);
    }

