    }

    /**
     * Pay-with-a-saved-card, server half. The checks run cheapest and least revealing first.
     *
     * <p>Every "not yours" case is a 404 that reads exactly like "does not exist" — a guest order,
     * another customer's order, another customer's card. A 403 would confirm the id is real.
     *
     * <p>The browser sends OUR card UUID; the {@code pm_...} token is looked up here and goes
     * straight to Stripe. It never appears in a request or a response.
     *
     * <p>Read-only as far as our database is concerned: the order only becomes PAID through the
     * same webhook / payment-status path as a newly typed card.
     */
    @Override
    @Transactional(readOnly = true)
    public void useSavedPaymentMethod(UUID orderId, UUID paymentMethodId, String userEmail) {
        if (userEmail == null) {
            throw ApiException.unauthorized("You must be signed in to pay with a saved card");
        }
        User user = userDAO.findByEmail(userEmail).orElseThrow(() -> ApiException.notFound("Order", orderId));

        // 1. The order must exist AND be this user's. A guest order has no user, so it fails here too.
        CustomerOrder order = orderDAO.findByPublicId(orderId)
                .filter(o -> o.getUser() != null && o.getUser().getId().equals(user.getId()))
                .orElseThrow(() -> ApiException.notFound("Order", orderId));

        // 2. Only an unpaid order can change how it is paid.
        if (order.getStatus() != OrderStatus.PENDING_PAYMENT) {
            throw ApiException.conflict("Order " + orderId + " is " + order.getStatus() + " and can no longer be paid");
        }

        // 3. There must be a PaymentIntent to point at the card.
        if (!stripeService.isConfigured() || order.getStripePaymentIntentId() == null) {
            throw ApiException.badRequest("Payment is not available for this order");
        }

        // 4. The card must be this user's and not deleted.
        UserPaymentMethod card = paymentMethodDAO
                .findOwned(user.getId(), paymentMethodId)
                .orElseThrow(() -> ApiException.notFound("Payment method", paymentMethodId));

        // 5. The checkout greys expired cards out, but the server is the one that decides.
        if (card.isExpiredAt(YearMonth.now())) {
            throw ApiException.badRequest("That card has expired. Please choose another card.");
        }

        // Every saved card was attached to this Customer when it was saved, so a missing id means
        // our data is inconsistent — fail clearly rather than send Stripe a request it will refuse.
        if (user.getStripeCustomerId() == null) {
            throw ApiException.badRequest("That card cannot be used. Please choose another card.");
        }

        // 6. Point the PaymentIntent at the card. Stripe's own message is logged, not returned:
        // it can describe our integration rather than anything the customer can act on.
        try {
            stripeService.attachSavedCardToPaymentIntent(
                    order.getStripePaymentIntentId(), user.getStripeCustomerId(), card.getStripePaymentMethodId());
            log.info("Order {} will be paid with saved card {}", orderId, paymentMethodId);
        } catch (StripeException ex) {
            // The order can be PAID at Stripe while still PENDING_PAYMENT here: paid in another tab,
            // with the webhook not yet arrived. Stripe then refuses to change the card, and "choose
            // another card" would invite the customer to pay twice. So ask Stripe what state the
            // payment is actually in, rather than guessing from the wording of its error.
            if (paymentAlreadySucceeded(order.getStripePaymentIntentId())) {
                log.info("Order {} is already paid at Stripe; refusing to change its card", orderId);
                throw ApiException.conflict("Order " + orderId + " has already been paid");
            }
            log.error("Stripe refused saved card {} for order {}", paymentMethodId, orderId, ex);
            throw ApiException.badRequest("That card could not be used for this order. Please choose another card.");
        }
    }

    /**
     * Whether Stripe reports this PaymentIntent as already paid.
     *
     * <p>Only asked AFTER Stripe refuses an update — checking first would cost a round trip on every
     * attempt and could still lose the race to a payment completing in between. If this check
     * itself fails, the answer is "not known to be paid" and the caller's ordinary error stands.
     */
    private boolean paymentAlreadySucceeded(String paymentIntentId) {
        try {
            PaymentIntent intent = stripeService.retrieve(paymentIntentId);
            return intent != null && "succeeded".equals(intent.getStatus());
        } catch (StripeException ex) {
            log.warn("Could not re-check PaymentIntent {} after a refused update", paymentIntentId, ex);
            return false;
        }
    }

    /**
     * Records WHICH card paid, for display on the confirmation page and order history.
     *
     * <p>Only the brand and last four digits are kept — the same display metadata Stripe reports.
     * The order deliberately does not keep the payment-method token: it needs to say which card was
     * used, never to be able to charge it again.
     *
     * <p>Best-effort. A failure here must never stop an order being marked paid — the customer's
     * money has already moved, and a missing "Visa ending 4242" is cosmetic.
     */
    private void captureCardDetails(CustomerOrder order, PaymentIntent intent) {
        try {
            String paymentMethodId = intent.getPaymentMethod();
            if (paymentMethodId == null) {
                return;
            }

            PaymentMethod method = stripeService.retrievePaymentMethod(paymentMethodId);
            PaymentMethod.Card card = method.getCard();

            if (card != null) {
                order.setCardBrand(card.getBrand());
                order.setCardLast4(card.getLast4());
                return;
            }

            /*
             * Not every payment method is a card.
             *
             * Stripe Elements also offers wallets — Link, Cash App Pay, Klarna — and those have no
             * `card` object at all, not on the PaymentMethod and not on the Charge either. Assuming
             * a card is always there is why this silently recorded nothing at first.
             *
             * So fall back to the payment method's TYPE. "Paid with Link" is honest and useful;
             * inventing a last4 that Stripe never gave us would not be.
             */
            order.setCardBrand(method.getType());
            order.setCardLast4(null);
        } catch (StripeException ex) {
            log.warn("Could not read the payment method used for order {}", order.getPublicId(), ex);
        }
    }

    private OrderDTO toDtoWithItems(UUID id) {
        return orderDAO.findByPublicIdWithItems(id)
                .map(mapper::mapCustomerOrderToOrderDTO)
                .orElseThrow(() -> ApiException.notFound("Order", id));
    }
}

